      "mode": "review",
      "guidance": 1,
      "competencyIds": [
        "sql-order-limit"
      ],
      "hints": [
        "Ask which clause decides the order of the rows and which clause decides how many of them there are."
      ],
      "misconceptions": [
        "Thinking a WHERE clause on the balance can stand in for an order and a limit.",
        "Thinking GROUP BY sorts the rows, when it gathers rows into groups."
      ],
